import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { computeIndicator, INDICATORS } from '../shared/indicators';

// Reference values generated by TA-Lib (tests/fixtures/gen_talib.py).
const F = JSON.parse(readFileSync(new URL('./fixtures/talib.json', import.meta.url), 'utf8')) as Record<string, (number | null)[]> & { closes: number[] };

function same(actual: (number | null)[], expected: (number | null)[], tol: number, from = 0) {
  expect(actual.length).toBe(expected.length);
  for (let i = from; i < expected.length; i++) {
    const e = expected[i], a = actual[i];
    if (e === null) { expect(a, `index ${i} should be warm-up`).toBeNull(); continue; }
    expect(a, `index ${i}`).not.toBeNull();
    expect(Math.abs(a! - e) / Math.max(1, Math.abs(e)), `index ${i}: ${a} vs ${e}`).toBeLessThan(tol);
  }
}

describe('indicators match TA-Lib', () => {
  const c = F.closes;
  it('SMA(20)', () => same(computeIndicator('sma', c, { period: 20 }).value, F.sma20, 1e-10));
  it('EMA(20), SMA-seeded', () => same(computeIndicator('ema', c, { period: 20 }).value, F.ema20, 1e-10));
  it('WMA(20)', () => same(computeIndicator('wma', c, { period: 20 }).value, F.wma20, 1e-10));
  it('Bollinger(20, 2)', () => {
    const b = computeIndicator('bbands', c, { period: 20, k: 2 });
    same(b.upper, F.bb_upper, 1e-9);
    same(b.mid, F.bb_mid, 1e-10);
    same(b.lower, F.bb_lower, 1e-9);
  });
  it('RSI(14), Wilder', () => same(computeIndicator('rsi', c, { period: 14 }).value, F.rsi14, 1e-9));
  it('ROC(10)', () => same(computeIndicator('roc', c, { period: 10 }).value, F.roc10, 1e-10));
  it('MACD(12,26,9) after convergence', () => {
    // TA-Lib aligns the fast EMA seed to the slow one; the two converge geometrically.
    const m = computeIndicator('macd', c, { fast: 12, slow: 26, signal: 9 });
    same(m.macd.slice(200), F.macd.slice(200), 1e-6);
    same(m.signal.slice(200), F.macd_signal.slice(200), 1e-6);
    same(m.hist.slice(200), F.macd_hist.slice(200), 1e-6);
  });
});

describe('indicator registry', () => {
  it('every indicator computes without throwing and keeps the input length', () => {
    const c = F.closes;
    for (const meta of INDICATORS) {
      const params = Object.fromEntries(meta.params.map((p) => [p.key, p.default]));
      const out = computeIndicator(meta.id, c, params, meta.needsOther ? c.map((x) => x * 1.1) : undefined);
      for (const k of meta.outputs) expect(out[k], `${meta.id}.${k}`).toHaveLength(c.length);
    }
  });
  it('clamps out-of-range params instead of producing garbage', () => {
    expect(() => computeIndicator('sma', [1, 2, 3], { period: -5 })).not.toThrow();
  });
  it('relative indicators refuse a misaligned second series', () => {
    expect(() => computeIndicator('corr', [1, 2, 3], {}, [1, 2])).toThrow(/second instrument/);
  });
});
